// Auth page design contract (owner design reference 2026-11-03 + his
// same-day correction): ONE page with a single card — the sign-up form
// first, the sign-in form swapped in via the option below it — plus the
// feature highlights from the reference, a working remember-me, and a
// terms gate. It must never grow dead buttons: no social sign-in row
// exists while no social provider is connected, and there is no
// chosen-username field (usernames are auto-generated by the database,
// R2-I decision).
import { describe, it, expect } from 'vitest'
import { readFileSync } from 'node:fs'
import { resolve } from 'node:path'

const screen = readFileSync(resolve(process.cwd(), 'src/components/AuthScreen.tsx'), 'utf8')
const env = readFileSync(resolve(process.cwd(), 'src/lib/supabaseEnv.ts'), 'utf8')
const client = readFileSync(resolve(process.cwd(), 'src/lib/supabase.ts'), 'utf8')

describe('auth page design contract', () => {
  it('renders the single card with sign-up and sign-in views plus the three feature highlights', () => {
    expect(screen).toContain('auth-card-signup')
    expect(screen).toContain('auth-card-signin')
    expect(screen).toContain("view === 'signup'")
    expect(screen).toContain("setView('signin')")
    expect(screen).toContain("t('authFeatureFreeTitle')")
    expect(screen).toContain("t('authFeatureSecureTitle')")
    expect(screen).toContain("t('authFeatureDevicesTitle')")
  })
  it('sign-up is gated on accepting the terms, with both legal texts reachable', () => {
    expect(screen).toContain('disabled={busy !== null || !suTerms}')
    expect(screen).toContain("setLegal('terms')")
    expect(screen).toContain("setLegal('privacy')")
  })
  it('remember-me is wired before sign-in, and the client storage routes by it', () => {
    expect(screen).toContain('setRememberSession(siRemember)')
    expect(env).toContain('export function setRememberSession')
    expect(client).toContain('sessionRemembered()')
    expect(client).toContain('sessionStorage')
  })
  it('no dead social buttons and no chosen-username field', () => {
    expect(screen).not.toMatch(/>\s*Google\s*</)
    expect(screen).not.toMatch(/>\s*GitHub\s*</)
    expect(screen).not.toMatch(/>\s*Apple\s*</)
    expect(screen).not.toContain('auth-social')
    expect(screen).not.toMatch(/autoComplete="username"/)
    expect(screen).toContain("t('usernameAutoNote')")
  })
  it('the display name is collected and passed to sign-up', () => {
    expect(screen).toContain("t('fullName')")
    expect(screen).toContain('signUpWithEmail(auth, suEmail, suPassword, suConfirm, suName)')
  })
})
